-- Create sub_claim_type enum
CREATE TYPE sub_claim_type AS ENUM (
  'POLICY',
  'THIRD_PARTY',
  'THIRD_PARTY_SETTLEMENT',
  'PRIVATE_REPAIR',
  'SHLOMO_POLICY',
  'SHLOMO_THIRD_PARTY'
);

-- Add new fields to cases table
ALTER TABLE cases
  ADD COLUMN IF NOT EXISTS customer_name     TEXT,
