-- =============================================================================
-- 010_fix_rls_ceo.sql
-- =============================================================================
-- Migration 010: Fix RLS INSERT policies to allow CEO
-- CEO has branch_id = NULL so the branch_id IN (...) check always fails for CEO

-- Fix cars INSERT: allow CEO to insert into any branch
DROP POLICY IF EXISTS cars_insert ON cars;
CREATE POLICY cars_insert ON cars FOR INSERT TO authenticated
  WITH CHECK (
    branch_id IN (SELECT branch_id FROM profiles WHERE id = auth.uid())
    OR EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND role = 'CEO')
  );

-- Fix cars UPDATE: allow CEO to update any car
DROP POLICY IF EXISTS cars_update ON cars;
CREATE POLICY cars_update ON cars FOR UPDATE TO authenticated
  USING (
    branch_id IN (SELECT branch_id FROM profiles WHERE id = auth.uid())
    OR EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND role = 'CEO')
  );

-- Fix cases INSERT: allow CEO to insert into any branch
DROP POLICY IF EXISTS cases_insert ON cases;
CREATE POLICY cases_insert ON cases FOR INSERT TO authenticated
  WITH CHECK (
    branch_id IN (SELECT branch_id FROM profiles WHERE id = auth.uid())
    OR EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND role = 'CEO')
  );

-- =============================================================================
-- 010_rls_case_workflow_fixes.sql
-- =============================================================================
-- Migration 010: RLS fixes for case creation and workflow step completion
-- 1) Allow inserting case_workflow_runs when the case was just created by the current user
--    (fixes "new row violates row-level security policy for table case_workflow_runs")
-- 2) Allow CEO to update case_workflow_runs and case_workflow_steps (branch_id may be null for CEO)

-- case_workflow_runs: INSERT for case creator (so createCase can add the run after inserting case)
CREATE POLICY case_workflow_runs_insert_creator ON case_workflow_runs
  FOR INSERT TO authenticated
  WITH CHECK (
    case_id IN (SELECT id FROM cases WHERE created_by = auth.uid())
  );

-- case_workflow_runs: UPDATE for CEO (e.g. when completing run)
CREATE POLICY case_workflow_runs_update_ceo ON case_workflow_runs
  FOR UPDATE TO authenticated
  USING (EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND role = 'CEO'));

-- case_workflow_steps: UPDATE for CEO (so CEO can complete steps)
CREATE POLICY case_workflow_steps_update_ceo ON case_workflow_steps
  FOR UPDATE TO authenticated
  USING (EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND role = 'CEO'));


-- =============================================================================
-- 011_fix_rls_workflow_steps_ceo.sql
-- =============================================================================
-- Migration 011: Fix RLS INSERT policy for case_workflow_steps to allow CEO
-- CEO has branch_id = NULL so the branch_id IN (...) check always fails.
-- The existing case_workflow_steps_insert policy blocks CEO from inserting steps.
-- Solution: add additive policy allowing CEO to insert any workflow step.

DROP POLICY IF EXISTS case_workflow_steps_insert_ceo ON case_workflow_steps;
CREATE POLICY case_workflow_steps_insert_ceo ON case_workflow_steps
  FOR INSERT TO authenticated
  WITH CHECK (
    EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND role = 'CEO')
  );

-- Also allow creator of the case to insert steps (covers SERVICE_MANAGER edge cases)
DROP POLICY IF EXISTS case_workflow_steps_insert_creator ON case_workflow_steps;
CREATE POLICY case_workflow_steps_insert_creator ON case_workflow_steps
  FOR INSERT TO authenticated
  WITH CHECK (
    run_id IN (
      SELECT cwr.id FROM case_workflow_runs cwr
      JOIN cases c ON c.id = cwr.case_id
      WHERE c.created_by = auth.uid()
    )
  );


-- =============================================================================
-- 012_fix_ceo_rls_and_approval_config.sql
-- =============================================================================
-- Migration 012: Fix CEO RLS INSERT policies + add requires_ceo_approval to workflow_step_templates
-- CEO has branch_id = NULL so branch_id IN (...) checks always fail for CEO

-- Fix case_workflow_runs INSERT: CEO needs to create closure workflow runs
DROP POLICY IF EXISTS case_workflow_runs_insert ON case_workflow_runs;
CREATE POLICY case_workflow_runs_insert ON case_workflow_runs FOR INSERT TO authenticated
  WITH CHECK (
    EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND role = 'CEO')
    OR case_id IN (SELECT id FROM cases WHERE branch_id IN (SELECT branch_id FROM profiles WHERE id = auth.uid()))
  );

-- Fix ceo_approvals INSERT: CEO (and service managers) need to insert approvals when completing steps
DROP POLICY IF EXISTS ceo_approvals_insert ON ceo_approvals;
CREATE POLICY ceo_approvals_insert ON ceo_approvals FOR INSERT TO authenticated
  WITH CHECK (
    EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND role = 'CEO')
    OR case_id IN (SELECT id FROM cases WHERE branch_id IN (SELECT branch_id FROM profiles WHERE id = auth.uid()))
  );

-- Add requires_ceo_approval field to workflow_step_templates
ALTER TABLE workflow_step_templates
  ADD COLUMN IF NOT EXISTS requires_ceo_approval BOOLEAN NOT NULL DEFAULT FALSE;

-- Set WAIT_APPRAISER_APPROVAL as requiring CEO approval (matching current hardcoded logic)
UPDATE workflow_step_templates
  SET requires_ceo_approval = TRUE
  WHERE step_key = 'WAIT_APPRAISER_APPROVAL';


