);

CREATE INDEX IF NOT EXISTS idx_painter_requests_case ON painter_requests(case_id);

ALTER TABLE painter_requests ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS painter_requests_select ON painter_requests;
